code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    positions = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                positions.setdefault(color, []).append((r, c))

    frames = []
    frame_colors = set()
    for color, cells in positions.items():
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        border = {(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                  if r in (r0, r1) or c in (c0, c1)}
        if set(cells) == border:
            frames.append((color, r0, r1, c0, c1))
            frame_colors.add(color)

    counts = Counter(color for color, cells in positions.items() if color not in frame_colors for _ in cells)
    out = [[0] * w for _ in range(h)]
    for color, r0, r1, c0, c1 in frames:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = color
        rlo, rhi, clo, chi = r0 + 1, r1 - 1, c0 + 1, c1 - 1
        needed = sum(1 for r in range(rlo, rhi + 1) for c in range(clo, chi + 1)
                    if (r-rlo + c-clo) % 2 == 0)
        match = [marker for marker, n in counts.items() if n == needed]
        if len(match) == 1:
            marker = match[0]
            for r in range(rlo, rhi + 1):
                for c in range(clo, chi + 1):
                    if (r-rlo + c-clo) % 2 == 0:
                        out[r][c] = marker
    return out
'''
